import type { Prayer } from "./prayerCategories";

export const NOVENA_PRAYERS_13: Prayer[] = [
  // NOVENA TO SAINT FRANCIS XAVIER
  // novenaId: "novenas-saint-francis-xavier"

  {
    id: "sfx-np-1",
    novenaId: "novenas-saint-francis-xavier",
    title: "Day 1 — The Call to the Missions",
    category: "novenas",
    day: 1,
    intention: "To hear and respond to God's call to evangelization",
    text: `O glorious Saint Francis Xavier, patron of missions and evangelizers, you who were born into privilege yet abandoned all comfort for the sake of the Gospel, intercede for me today. You heard the call of Christ echoing through the words of Saint Ignatius: "What does it profit a man to gain the whole world and lose his soul?" And you answered with your entire life. I pray today that I may hear that same call in the depths of my heart — the call to bring the light of Christ to those who sit in darkness. Give me the courage to leave behind whatever keeps me from full surrender to God's mission. Let me not count the cost, but trust that the Lord who calls me will also provide for every need. O Saint Francis, who crossed oceans for souls, set my heart on fire with missionary zeal. Amen.`,
  },
  {
    id: "sfx-np-2",
    novenaId: "novenas-saint-francis-xavier",
    title: "Day 2 — The zeal of the Apostle of the Indies",
    category: "novenas",
    day: 2,
    intention: "For burning zeal in sharing the faith",
    text: `O Saint Francis Xavier, Apostle of the Indies and Japan, you who baptized thousands with your own hands and traveled thousands of miles on foot and by sea, obtain for me a share in your apostolic zeal. You wrote to Saint Ignatius from India: "I have no rest in my body, for I have no more news of the conversion of souls." Your heart burned with the same fire that consumed the apostles at Pentecost. Ignite that same fire in my soul. Let me never grow complacent in my faith, never be satisfied with my own salvation while others perish without hearing the name of Jesus. Grant me the grace to speak of Christ to everyone I meet, with words and actions that draw others to the beauty of the Gospel. O Francis, whose heart burned for the salvation of souls, inflame my heart with the same divine love. Amen.`,
  },
  {
    id: "sfx-np-3",
    novenaId: "novenas-saint-francis-xavier",
    title: "Day 3 — Poverty for the sake of the Gospel",
    category: "novenas",
    day: 3,
    intention: "To embrace holy poverty and detachment",
    text: `O Saint Francis Xavier, you who stripped yourself of worldly wealth and comfort to follow Christ in radical poverty, teach me the liberating power of detachment. You left behind the wealth of your Basque noble family, the prestige of the University of Paris, and the security of a comfortable life, to carry nothing but a crucifix and a lantern into the mission fields of Asia. You discovered what the saints have always known: that he who possesses God possesses all things, and he who possesses nothing for God's sake possesses the greatest freedom. Help me to loosen my grip on the things of this world — money, status, comfort, approval — and to cling instead to the treasures of heaven. Let me find my security not in what I own, but in Whom I serve. O Francis, who found true riches in evangelical poverty, teach me to store up treasures in heaven. Amen.`,
  },
  {
    id: "sfx-np-4",
    novenaId: "novenas-saint-francis-xavier",
    title: "Day 4 — The Love of Souls",
    category: "novenas",
    day: 4,
    intention: "To love every soul as Christ loves them",
    text: `O Saint Francis Xavier, you loved souls with the very love of Jesus Christ. You saw in every pagan face the countenance of a redeemable child of God. You wept over those who had never heard the Gospel, you rejoiced over every baptism, and you labored without ceasing until every village in your path had heard the good news. Obtain for me this same love for souls — a love that is not content with private holiness, but must share the treasure of faith with others. Help me to see every person I encounter as someone for whom Christ died, someone worthy of my prayers, my sacrifices, and my witness. Remove from my heart all indifference, all laziness, all fear of rejection, and replace them with a tender, relentless compassion for the lost and the hurting. O Francis, who loved souls as Christ loved them, teach me to love as you loved. Amen.`,
  },
  {
    id: "sfx-np-5",
    novenaId: "novenas-saint-francis-xavier",
    title: "Day 5 — Perseverance in Adversity",
    category: "novenas",
    day: 5,
    intention: "To persevere through trials in mission work",
    text: `O Saint Francis Xavier, you faced countless hardships in your missionary journeys — storms at sea, tropical diseases, hostile natives, exhaustion, loneliness, and the constant threat of death. Yet you never surrendered to despair. When your body was weak, your spirit was strong. When doors closed, you found other doors. When one people rejected the Gospel, you moved on to the next. I ask you today to grant me the same perseverance. When I face obstacles in my work for God, when my efforts seem fruitless, when my health fails or my spirit grows weary, remind me that the harvest is the Lord's and my duty is simply to sow the seed in faith. Give me the strength to endure every trial with patience and trust, knowing that God's grace is sufficient and that the seeds I plant will bear fruit in His timing. O Francis, who persevered through every storm, obtain for me the grace of holy perseverance. Amen.`,
  },
  {
    id: "sfx-np-6",
    novenaId: "novenas-saint-francis-xavier",
    title: "Day 6 — The Holy Sacraments",
    category: "novenas",
    day: 6,
    intention: "For a deeper love of the sacraments",
    text: `O Saint Francis Xavier, you who celebrated Mass with trembling reverence and spent hours in the confessional hearing the sins of converts, obtained for me a deeper love for the holy sacraments of the Church. You carried the Holy Eucharist into villages that had never known the Real Presence, and you baptized thousands in rivers, pools, and the open sea. The sacraments were the lifeblood of your mission, and they must be the lifeblood of my spiritual life as well. Help me to approach the altar with the same awe and gratitude with which you approached it. Help me to receive Confession with true contrition and sincere purpose of amendment. Help me to understand that every Mass I attend is a participation in the eternal heavenly liturgy, and that every sacrament I receive is an encounter with the living God. O Francis, apostle of the sacraments, renew my love for these channels of divine grace. Amen.`,
  },
  {
    id: "sfx-np-7",
    novenaId: "novenas-saint-francis-xavier",
    title: "Day 7 — Missionary Courage",
    category: "novenas",
    day: 7,
    intention: "For boldness in proclaiming the Gospel",
    text: `O Saint Francis Xavier, you who entered foreign lands with no guarantee of safety, no knowledge of the language, and no certainty of success, obtain for me a holy boldness in proclaiming the Gospel. You did not wait until you were perfectly prepared; you went forth in faith, trusting that the Holy Spirit would fill your mouth with the right words. You did not fear the powerful or the hostile; you spoke the truth with charity and conviction. I ask you today to remove from me all timidity, all embarrassment about my faith, all fear of what others might think. Fill me with the courage of the apostles, who spoke boldly in the face of persecution and counted it a privilege to suffer for the name of Jesus. Help me to remember that the Gospel is the power of God for salvation, and that my task is simply to share it, leaving the results to God. O Francis, whose courage converted nations, make me bold for Christ. Amen.`,
  },
  {
    id: "sfx-np-8",
    novenaId: "novenas-saint-francis-xavier",
    title: "Day 8 — Intercession for the Unreached",
    category: "novenas",
    day: 8,
    intention: "For the peoples who have not yet heard the Gospel",
    text: `O Saint Francis Xavier, you who died on the island of Shangchuan while waiting to enter China, your heart still burning with desire to bring Christ to the unreached, intercede today for all the peoples of the world who have never heard the name of Jesus. There are still millions who live and die without ever knowing the Good News, without ever receiving the sacraments, without ever experiencing the love of the Christian community. I pray for the missionaries who serve among them, that they may be strengthened in their vocation. I pray for the local churches in mission lands, that they may grow and flourish. I pray for the generosity of the faithful, that they may support the missions with their prayers, their alms, and their own vocations. And I pray that God may raise up new Francis Xaviers — men and women willing to go to the ends of the earth for the sake of the Kingdom. O Francis, patron of the unreached, hear our prayer for the missions of the Church. Amen.`,
  },
  {
    id: "sfx-np-9",
    novenaId: "novenas-saint-francis-xavier",
    title: "Day 9 — The Eternal Harvest",
    category: "novenas",
    day: 9,
    intention: "To labor faithfully for the heavenly reward",
    text: `O glorious Saint Francis Xavier, on this final day of my novena, I commend myself to your powerful intercession. You who labored so faithfully for Christ in the mission fields of India, Japan, and Southeast Asia, and who died with the words of Jesus on your lips — "Increase, O Lord, our faith" — pray for me now. Help me to live each day as a missionary, wherever God has placed me — in my home, my workplace, my neighborhood, my parish. Let me never forget that the mission field is not only in distant lands but also in the hearts of those closest to me. Grant me the grace to labor faithfully for the heavenly harvest, to plant seeds of faith with patience, to water them with prayer, and to trust God for the increase. And when my earthly mission is complete, may I join you and all the saints in the eternal liturgy of heaven, where every tribe and tongue and nation worships the Lamb who was slain. O Saint Francis Xavier, Apostle of the Indies, pray for us and for all the missions of the Church. Amen.`,
  },

  // NOVENA TO SAINT IGNATIUS OF LOYOLA
  // novenaId: "novenas-saint-ignatius-loyola"

  {
    id: "sil-np-1",
    novenaId: "novenas-saint-ignatius-loyola",
    title: "Day 1 — The Conversion at Loyola",
    category: "novenas",
    day: 1,
    intention: "For a deeper conversion of heart",
    text: `O glorious Saint Ignatius of Loyola, founder of the Society of Jesus and master of the spiritual life, you who were transformed from a vain soldier into a holy saint by the grace of God working through a cannonball wound, intercede for me today. In that long months of convalescence, when you could no longer pursue worldly glory, God opened your eyes to the greater glory of heaven. You read the lives of the saints and the Gospels, and your heart was set ablaze with a new desire — not for the honors of the world, but for the greater glory of God. I ask you today to obtain for me the grace of a deep and lasting conversion. Not just the initial conversion of coming to faith, but the daily, ongoing conversion of turning away from sin and toward God with my whole heart. O Ignatius, who was remade by grace, remake me in the image of Christ. Amen.`,
  },
  {
    id: "sil-np-2",
    novenaId: "novenas-saint-ignatius-loyola",
    title: "Day 2 — The Spiritual Exercises",
    category: "novenas",
    day: 2,
    intention: "To make a good spiritual retreat",
    text: `O Saint Ignatius, author of the Spiritual Exercises, those magnificent thirty days of prayer and meditation that have transformed countless souls, obtain for me the grace to make a good retreat. The Exercises are a school of prayer, a laboratory of discernment, and a workshop of the soul where God fashions instruments for His divine purposes. I pray that I may have the opportunity to make even a short retreat, and that during that time God may speak to my heart with clarity and power. If I cannot make a formal retreat, help me to apply the principles of the Exercises to my daily life — to make good decisions, to discern the movements of spirits, and to order my life around the supreme goal of loving and serving God. O Ignatius, master of the interior life, guide me in the sacred art of discernment. Amen.`,
  },
  {
    id: "sil-np-3",
    novenaId: "novenas-saint-ignatius-loyola",
    title: "Day 3 — Finding God in All Things",
    category: "novenas",
    day: 3,
    intention: "To discover God's presence in daily life",
    text: `O Saint Ignatius, you taught us that God can be found in all things — that every creature, every event, every moment is a window through which the divine light shines. This is the hallmark of Ignatian spirituality: the conviction that there is no division between the sacred and the secular, but that all of life is sacred when lived for the greater glory of God. I ask you today to open my eyes to the presence of God in the ordinary events of my day — in the faces of the people I meet, in the work of my hands, in the beauty of creation, in the challenges and setbacks that come my way. Help me to find consolation in God's presence, desolation in its absence, and to make all things new by offering them to the Lord. O Ignatius, who found God in all things, teach me to see His hand at work in every corner of my life. Amen.`,
  },
  {
    id: "sil-np-4",
    novenaId: "novenas-saint-ignatius-loyola",
    title: "Day 4 — Discernment of Spirits",
    category: "novenas",
    day: 4,
    intention: "To discern God's will with clarity",
    text: `O Saint Ignatius, you who mastered the art of discernment of spirits, teach me to recognize the movements of God's grace in my soul. You taught that the good spirit moves with peace, clarity, and generosity, while the evil spirit moves with anxiety, confusion, and discouragement. I need this discernment now, Lord, for I face decisions that are beyond my natural wisdom. Show me which path leads to Your glory and my deepest fulfillment. Help me to recognize the consolations that come from You and the desolations that come from the enemy. Give me the wisdom to act on what I discern and the courage to follow where You lead, even when the way is difficult and the outcome uncertain. O Ignatius, teacher of discernment, be my guide in the complex landscape of spiritual decision-making. Amen.`,
  },
  {
    id: "sil-np-5",
    novenaId: "novenas-saint-ignatius-loyola",
    title: "Day 5 — The Greater Glory of God",
    category: "novenas",
    day: 5,
    intention: "To live for the greater glory of God",
    text: `O Saint Ignatius, your great motto was "Ad maiorem Dei gloriam" — for the greater glory of God. You ordered your entire life, and the life of the entire Jesuit order, around this supreme principle. I pray today that this may become the guiding principle of my life as well. Help me to make every decision, undertake every task, and endure every trial for the greater glory of God. When I am tempted to seek my own glory, remind me that all glory belongs to God. When I am tempted to take the easy path, remind me that the greater good often requires the greater sacrifice. When I am tempted to despair of making a difference, remind me that God can do infinitely more with my small offering than I could ever accomplish on my own. O Ignatius, whose life was a hymn to the greater glory of God, make my life a living offering to His divine majesty. Amen.`,
  },
  {
    id: "sil-np-6",
    novenaId: "novenas-saint-ignatius-loyola",
    title: "Day 6 — The Magis",
    category: "novenas",
    day: 6,
    intention: "To always choose the greater good",
    text: `O Saint Ignatius, you taught us the meaning of the "magis" — not merely doing more, but always choosing the greater good, the more generous option, the path that leads most directly to God. The magis is not about quantity but quality, not about busyness but about depth of love. I ask you today to help me cultivate this Ignatian spirit of excellence. When I face choices between the good and the better, give me the courage to choose the better. When I am tempted to settle for mediocrity in my spiritual life, inspire me to reach for the heights of holiness. When I am tempted to give less than my best in my duties, remind me that God deserves the firstfruits of my time, my talent, and my treasure. O Ignatius, who always chose the greater good, form in me a heart that desires and pursues the magis in all things. Amen.`,
  },
  {
    id: "sil-np-7",
    novenaId: "novenas-saint-ignatius-loyola",
    title: "Day 7 — Education and the Formation of Persons",
    category: "novenas",
    day: 7,
    intention: "For Catholic education and formation",
    text: `O Saint Ignatius, you who established schools and universities throughout the world, believing that the formation of the mind is inseparable from the formation of the soul, intercede for Catholic education today. In a world of confusion and relativism, the Church needs schools that form not just intelligent minds but holy hearts — schools that teach young people to think with the Church, to discern God's will, and to live for the greater glory of God. I pray for all teachers and professors, administrators and students, parents and catechists. Give them the wisdom to unite faith and reason, the courage to proclaim truth in a hostile environment, and the love to form disciples of Christ. I pray also for my own ongoing formation, that I may never stop learning, growing, and deepening my knowledge and love of God. O Ignatius, patron of educators, bless and protect the work of Catholic formation in our time. Amen.`,
  },
  {
    id: "sil-np-8",
    novenaId: "novenas-saint-ignatius-loyola",
    title: "Day 8 — Indifference and Attachment",
    category: "novenas",
    day: 8,
    intention: "To practice holy indifference before God's will",
    text: `O Saint Ignatius, you taught the radical Ignatian principle of spiritual indifference — not indifference to God or to souls, but indifference to all created things insofar as they do not lead me closer to God. You asked me to stand before God as an empty vessel, ready to receive whatever He wills, whether health or sickness, poverty or wealth, success or failure, life or death. This is the freedom of the children of God. I confess, dear saint, that I am often very far from this indifference. I cling to my comforts, my preferences, my plans, and my reputation. Detach me, Lord, from everything that holds me back from total surrender. Help me to say with the Virgin Mary, "Behold the handmaid of the Lord; be it done to me according to your word." O Ignatius, who achieved perfect indifference before God's holy will, obtain for me this same holy freedom. Amen.`,
  },
  {
    id: "sil-np-9",
    novenaId: "novenas-saint-ignatius-loyola",
    title: "Day 9 — A Life for God's Greater Glory",
    category: "novenas",
    day: 9,
    intention: "To consecrate my life entirely to God",
    text: `O glorious Saint Ignatius of Loyola, on this final day of my novena, I consecrate myself anew to the greater glory of God. You gave everything to God — your noble birth, your military career, your physical health, your intellectual gifts, your very life — and God gave you back a hundredfold. You who were once a proud soldier became a humble servant of Christ, the founder of a great religious order, a mystic of profound depth, and a saint whose influence continues to shape the Church and the world. I ask you to obtain for me the grace to give God everything in my own life — without reservation, without calculation, without fear. Help me to live each day for His greater glory, to make all my decisions in His light, and to trust that He who began the good work in me will bring it to completion. O Ignatius, whose life was entirely for God's greater glory, obtain for me the grace of complete surrender to the divine will. Amen.`,
  },

  // NOVENA TO SAINT TERESA OF ÁVILA
  // novenaId: "novenas-saint-teresa-avila"

  {
    id: "sta-np-1",
    novenaId: "novenas-saint-teresa-avila",
    title: "Day 1 — The Journey to the Interior Castle",
    category: "novenas",
    day: 1,
    intention: "To begin the journey inward to God",
    text: `O glorious Saint Teresa of Ávila, Doctor of the Church and mistress of the interior life, you who described the soul as a castle with many dwelling places, intercede for me as I begin this journey to the center of my being where God dwells. You teach that the spiritual life is not merely about external practices of devotion, but about a profound journey inward, through the rooms of the soul, to the very center where the King resides. I confess that I have too often neglected this interior life, spending my energy on external activities while the well of my soul runs dry. Help me today to begin the journey inward — to be still, to be silent, to enter the first dwelling place of the castle where humble self-knowledge prepares the way for encounter with God. O Teresa, who found God in the center of your soul, lead me along the path of interior prayer. Amen.`,
  },
  {
    id: "sta-np-2",
    novenaId: "novenas-saint-teresa-avila",
    title: "Day 2 — The Prayer of Quiet",
    category: "novenas",
    day: 2,
    intention: "To grow in contemplative prayer",
    text: `O Saint Teresa, you who taught the different forms of prayer with such clarity and wisdom, obtain for me the grace to progress from vocal prayer to meditative prayer and beyond, to the prayer of quiet and the prayer of union. You described the prayer of quiet as a supernatural communication from God that touches the soul directly, beyond the faculties of the mind and will. It is a gift of grace that cannot be earned through effort alone, but only received in humble openness. Help me to prepare the soil of my soul through fidelity in meditation, patient perseverance, and genuine humility, so that when the Lord chooses to bestow this gift, I may be ready to receive it. Remove from my heart the distractions, attachments, and fears that prevent me from entering into deeper communion with God. O Teresa, teacher of contemplative prayer, guide me deeper into the interior castle. Amen.`,
  },
  {
    id: "sta-np-3",
    novenaId: "novenas-saint-teresa-avila",
    title: "Day 3 — Self-Knowledge and Humility",
    category: "novenas",
    day: 3,
    intention: "To grow in genuine humility",
    text: `O Saint Teresa, you taught that the first step on the spiritual journey is honest self-knowledge — seeing ourselves as we truly are in the light of God's truth, without the distortions of pride or despair. You wrote: "Self-knowledge is so important that, even if you were raised from the dead, you should not do anything of what you intended to do until you possessed it." I ask you today to grant me this holy self-knowledge. Help me to see my gifts without pride and my faults without discouragement. Show me where I am attached to vanity, where I seek human approval rather than God's glory, where I harbor secret sins that I have not confessed. Give me the courage to acknowledge my weakness and the confidence to trust in God's mercy. O Teresa, who found freedom in humble self-knowledge, grant me this essential grace. Amen.`,
  },
  {
    id: "sta-np-4",
    novenaId: "novenas-saint-teresa-avila",
    title: "Day 4 — The Watered Garden",
    category: "novenas",
    day: 4,
    intention: "To nurture the garden of my soul",
    text: `O Saint Teresa, you used the beautiful image of the garden to describe the soul's relationship with God. You compared the soul to four kinds of water — water drawn with effort, water from a well, water from a stream, and water from rain — representing the increasing graces God gives as the soul grows in prayer. I ask you today to help me tend the garden of my soul. Remove the weeds of sin, the thorns of attachment, and the rocks of spiritual laziness. Water the soil of my heart with prayers of contrition and devotion. Let the flowers of virtue bloom and the fruits of the Spirit flourish. Help me to be patient with the slow growth that is often the work of grace, and to trust that the Gardener knows what He is doing, even when I cannot see the progress. O Teresa, wise gardener of the soul, help me to cooperate with God's work in my interior life. Amen.`,
  },
  {
    id: "sta-np-5",
    novenaId: "novenas-saint-teresa-avila",
    title: "Day 5 — The Three Signs of True Prayer",
    category: "novenas",
    day: 5,
    intention: "To discern authentic prayer from self-deception",
    text: `O Saint Teresa, you gave the Church three signs by which we may know that our prayer is truly coming from God and not from self-deception or the enemy: it produces humility and self-knowledge, it increases faith and hope, and it draws the soul to love God and neighbor. I ask you today to examine my prayer life by these three signs. Does my prayer make me more humble, or more self-satisfied? Does it increase my trust in God, or merely my trust in my own spiritual abilities? Does it draw me to love others more generously, or does it leave me unchanged in my selfishness? If my prayer falls short of these standards, merciful Lord, purify it and deepen it. Teach me to pray not for my own spiritual consolation alone, but for your glory and the good of souls. O Teresa, whose prayer was pure and powerful, teach me to pray as you prayed. Amen.`,
  },
  {
    id: "sta-np-6",
    novenaId: "novenas-saint-teresa-avila",
    title: "Day 6 — The Interior Recollection",
    category: "novenas",
    day: 6,
    intention: "To practice the presence of God",
    text: `O Saint Teresa, you taught the practice of interior recollection — the habit of withdrawing the senses from external distractions and centering the soul in the presence of God. You described three stages of recollection: the recollection of the senses, which prepares for meditation; the recollection of the mind, which deepens into contemplation; and the recollection of the soul, which is the union with God. I pray today for the grace to cultivate this habit of recollection in my daily life. When I am busy with work, help me to keep God in the center of my heart. When I am with others, help me to see Christ in their faces. When I am alone, help me to be still and know that He is God. Let me not waste the present moment in distraction or anxiety, but fill each moment with the quiet awareness of God's loving presence. O Teresa, mistress of recollection, teach me to live in God's presence always. Amen.`,
  },
  {
    id: "sta-np-7",
    novenaId: "novenas-saint-teresa-avila",
    title: "Day 7 — Suffering and Redemptive Love",
    category: "novenas",
    day: 7,
    intention: "To offer my sufferings to God",
    text: `O Saint Teresa, you suffered greatly in your life — from illness, from opposition, from misunderstanding, from the pain of reforming a reluctant Church. Yet you offered all your sufferings to God with love and patience, and they became the furnace in which your sanctity was refined. You wrote: "Patience obtains all things." I ask you today to help me embrace my own sufferings — the physical pains, the emotional wounds, the spiritual trials — and to offer them to God as a sacrifice of love. When illness overwhelms me, give me patience. When I am misunderstood, give me trust in God. When I face failure, give me the humility to begin again. Help me to unite my small crosses to the great Cross of Christ, and to trust that God is using my suffering to purify my soul and to obtain graces for others. O Teresa, who suffered with heroic patience, teach me to offer my crosses with love. Amen.`,
  },
  {
    id: "sta-np-8",
    novenaId: "novenas-saint-teresa-avila",
    title: "Day 8 — The Reform of the Church",
    category: "novenas",
    day: 8,
    intention: "For the renewal and reform of the Church",
    text: `O Saint Teresa, you were called by God to reform the Carmelite order at a time when religious life had grown lax and comfortable. You faced fierce opposition, legal battles, and personal attacks, yet you persevered because you knew that God had called you to this work. I pray today for the renewal and reform of the Church in our time. The Church faces challenges that seem insurmountable — secularism, division, scandal, declining vocations, loss of faith. Yet You, Lord, are the Lord of history, and the gates of hell shall not prevail against Your Church. I ask you, Saint Teresa, to intercede for the Church, that God may raise up holy leaders who will lead the reform that is needed. Help me to do my part — to pray faithfully, to live my faith authentically, to support the work of renewal, and to trust that God is always doing a new thing in His Church. O Teresa, reformer of religious life, intercede for the reform of the whole Church. Amen.`,
  },
  {
    id: "sta-np-9",
    novenaId: "novenas-saint-teresa-avila",
    title: "Day 9 — The Living Water of Contemplation",
    category: "novenas",
    day: 9,
    intention: "To reach the highest places of prayer",
    text: `O glorious Saint Teresa of Ávila, Doctor of the Church, on this final day of my novena, I implore your powerful intercession. You who ascended the seven dwelling places of the interior castle and reached the center where God dwells in perfect union, obtain for me the grace to continue my journey deeper into the life of prayer. I know that I cannot reach the heights of contemplation by my own efforts — it is the work of divine grace. But I can cooperate by being faithful to prayer, open to God's action, and detached from everything that hinders the soul's flight to God. I ask you to pray that the Holy Spirit may lead me from glory to glory, from one degree of holiness to the next, until I reach the fullness of union with God. Help me to remain faithful to the end, to persevere through dryness and darkness, and to trust that God is always at work in the deepest places of my soul. O Teresa, mystic and Doctor of the interior life, lead me to the living water that springs up to eternal life. Amen.`,
  },

  // NOVENA TO SAINT JOHN OF THE CROSS
  // novenaId: "novenas-saint-john-cross"

  {
    id: "sjc-np-1",
    novenaId: "novenas-saint-john-cross",
    title: "Day 1 — The Dark Night of the Soul",
    category: "novenas",
    day: 1,
    intention: "To trust God in spiritual darkness",
    text: `O glorious Saint John of the Cross, Doctor of the Church and mystic of the dark night, you who endured the profound darkness of the soul and emerged into the brilliant light of divine union, intercede for me today. You teach that the dark night is not God's abandonment but His purifying work — the night in which He weans the soul from its attachment to sensible consolations and leads it to a deeper, more naked faith. I confess that I fear the darkness, that I cling to the light I can see and feel, and that I mistake the absence of consolation for the absence of God. Teach me, dear saint, to trust in the darkness, to believe when I cannot see, to hope when I feel nothing, and to love when all consolations have been withdrawn. O John, who found God in the darkest night, teach me to trust the God who works in darkness. Amen.`,
  },
  {
    id: "sjc-np-2",
    novenaId: "novenas-saint-john-cross",
    title: "Day 2 — The Purgation of the Senses",
    category: "novenas",
    day: 2,
    intention: "To be purified of attachment to sensory pleasures",
    text: `O Saint John of the Cross, you taught that the first stage of the dark night is the purgation of the external senses — the withdrawal of God's sensible consolations so that the soul may learn to seek God in faith alone rather than in feelings. This is the night of the senses, where the prayer that once brought consolation now feels dry, where the sacraments that once moved us to tears now leave us unmoved, where the spiritual exercises that once thrilled us now bore us. I ask you today to help me understand that this dryness is not punishment but purification. God is not taking Himself from me; He is removing my attachment to the gifts so that I may seek the Giver. Help me to persevere in prayer even when it feels fruitless, to receive the sacraments even when they seem dry, and to trust that God is at work in the deepest places of my soul, even when I feel nothing. O John, doctor of the dark night, purify my heart of all disordered attachments. Amen.`,
  },
  {
    id: "sjc-np-3",
    novenaId: "novenas-saint-john-cross",
    title: "Day 3 — The Night of the Spirit",
    category: "novenas",
    day: 3,
    intention: "To surrender to God's deep purification",
    text: `O Saint John of the Cross, you teach that after the night of the senses comes the far more profound and painful night of the spirit — a purgation so deep that the soul feels abandoned by God, overwhelmed by its own misery, and incapable of any spiritual good. In this night, even the most advanced souls are tempted to despair. I pray today for all who are experiencing this deep trial — those who feel that God has left them, those who cannot find Him in prayer or sacrament, those who are overwhelmed by their own unworthiness. Give me the faith to believe that even in this deepest darkness, God is nearer than ever, working His greatest work of transformation in the soul. Help me to surrender completely to this purifying action, to resist the temptation to flee from it, and to trust that the dawn will come. O John, who passed through the night of the spirit and emerged into union with God, sustain me in my own dark nights. Amen.`,
  },
  {
    id: "sjc-np-4",
    novenaId: "novenas-saint-john-cross",
    title: "Day 4 — Naked Faith",
    category: "novenas",
    day: 4,
    intention: "To practice faith without consolations",
    text: `O Saint John of the Cross, you teach the supreme importance of naked faith — faith that believes without feeling, hopes without seeing, and loves without consolation. This is the purest and most powerful form of faith, the faith that moves mountains and conquers the world. You wrote: "To come to possess all, desire the possession of nothing. To arrive at being all, desire to be nothing. To come to the knowledge of all, desire the knowledge of nothing." I ask you today to strengthen my naked faith. Help me to believe the truths of the Catholic faith even when my mind is assailed by doubts. Help me to hope in God's promises even when circumstances seem hopeless. Help me to love God above all things even when He seems distant and silent. Strip me of every false support, every spiritual crutch, every consolation that substitutes for the pure encounter with God in faith. O John, master of naked faith, teach me to walk by faith alone. Amen.`,
  },
  {
    id: "sjc-np-5",
    novenaId: "novenas-saint-john-cross",
    title: "Day 5 — Love as the Meaning of Suffering",
    category: "novenas",
    day: 5,
    intention: "To unite all suffering to the Cross of Christ",
    text: `O Saint John of the Cross, you who suffered with Christ on the Cross — both physically, in your imprisonment at Toledo, and spiritually, in the dark night of the soul — teach me the redemptive meaning of suffering. You did not flee from suffering; you embraced it with love, and through that love it became a participation in the saving work of Christ. You wrote: "In the inner stillness of the soul, the supreme Shepherd tends His flock." Even in the midst of suffering, God is present as the Good Shepherd, caring for His beloved. Help me to offer my sufferings — whether in body, mind, or spirit — to God as a sacrifice of love. Help me to unite them to the Passion of Christ, and to trust that they have value in His sight. O John, who found love in the midst of suffering, teach me to unite my crosses to the Cross of Christ. Amen.`,
  },
  {
    id: "sjc-np-6",
    novenaId: "novenas-saint-john-cross",
    title: "Day 6 — The Living Flame of Love",
    category: "novenas",
    day: 6,
    intention: "To be consumed by the fire of divine love",
    text: `O Saint John of the Cross, you wrote the great poem and commentary known as "The Living Flame of Love," in which you describe the soul's experience of being consumed by the fire of divine love. In this state, the soul is so united to God that it is as if the soul itself has become fire, burning with the love of the Beloved. I pray today that the Holy Spirit may kindle in my heart this living flame of love. Purify my heart of everything that is not love, every selfish desire, every resentment, every fear. Set my soul on fire with a love so strong that it burns away all dross and leaves only the pure gold of charity. Help me to love God above all things, to love my neighbor as myself, and to love myself as God loves me — with a love that is patient, kind, generous, and self-giving. O John, whose heart burned with the living flame of love, inflame my heart with the same divine fire. Amen.`,
  },
  {
    id: "sjc-np-7",
    novenaId: "novenas-saint-john-cross",
    title: "Day 7 — The Spiritual Canticle",
    category: "novenas",
    day: 7,
    intention: "To experience the union of the soul with Christ the Bridegroom",
    text: `O Saint John of the Cross, author of the sublime "Spiritual Canticle," you describe the soul's journey as a love story between the soul and Christ the Bridegroom. The soul searches through the night, calling for the Beloved, and at last finds Him in an intimate union that fills the heart with inexpressible joy. I pray today that I may experience something of this intimate union with Christ. I am the Bride, and He is the Bridegroom; the whole of my life is a love story between the soul and God. Help me to seek the Beloved with all my heart, to call upon Him in the darkness, to trust that He is drawing near even when I cannot perceive Him. Let every moment of my life be a step closer to the intimate embrace of divine love. O John, whose soul was ravished by the Beloved, lead me to the intimate union with Christ that is the destiny of every soul. Amen.`,
  },
  {
    id: "sjc-np-8",
    novenaId: "novenas-saint-john-cross",
    title: "Day 8 — Detachment and Letting Go",
    category: "novenas",
    day: 8,
    intention: "To let go of everything that is not God",
    text: `O Saint John of the Cross, you taught the most radical form of detachment — letting go not only of sinful attachments, but of all attachments that stand between the soul and God, even good things that become obstacles when they are loved more than God. You wrote: "If a person wishes to be sure of the road he treads on, he must close his eyes and walk in the dark." I ask you today to help me practice this radical detachment. Show me what I cling to that keeps me from total surrender to God. It may be my reputation, my comfort, my plans, my relationships, my possessions — any of these can become false gods if I place them above the Creator. Give me the courage to let go, the faith to trust that what I release will be replaced by something infinitely greater, and the love to desire nothing but God Himself. O John, master of holy detachment, teach me the freedom of letting go. Amen.`,
  },
  {
    id: "sjc-np-9",
    novenaId: "novenas-saint-john-cross",
    title: "Day 9 — The Dawn of Divine Union",
    category: "novenas",
    day: 9,
    intention: "To attain the fullness of union with God",
    text: `O glorious Saint John of the Cross, Doctor of the Church and master of the mystical life, on this final day of my novena, I implore your intercession. You who passed through the darkest night and emerged into the brilliant dawn of divine union, pray for me. I may not reach the heights of mystical union in this life, but I pray that every day I may grow closer to God — through faith, through love, through the patient endurance of the dark nights that are part of every Christian's journey. Help me to persevere in prayer, to trust in God's purifying work, and to hope in the promises of Christ. When the darkness comes, remind me that the dawn is near. When I feel abandoned, remind me that God is closest when He seems most distant. When I am tempted to give up, remind me that the saints before me passed through the same darkness and emerged into the light of glory. O John of the Cross, mystic and poet of divine love, pray for me now and at the hour of my death. Amen.`,
  },

  // NOVENA TO THE HOLY MARTYRS
  // novenaId: "novenas-holy-martyrs"

  {
    id: "shm-np-1",
    novenaId: "novenas-holy-martyrs",
    title: "Day 1 — The Blood of the Martyrs",
    category: "novenas",
    day: 1,
    intention: "For courage to witness to Christ in all circumstances",
    text: `O Holy Martyrs of Christ, faithful witnesses who sealed your faith with your blood, intercede for me today. You who lived in the arena of the Colosseum, the sands of the desert, the prisons of Rome, the executioner's block — you chose death rather than denial of the Lord Jesus. Tertullian wrote: "The blood of the martyrs is the seed of the Church." Your sacrifice was not in vain; from your deaths sprang the greatest civilization the world has ever known. I pray today for the courage to witness to Christ in every circumstance of my life — not only in the dramatic moments, but in the quiet, daily choices that define the Christian life. Help me to speak the truth with charity, to stand firm in my convictions, and to live my faith authentically, even when it costs me. O Holy Martyrs, obtain for me the grace of holy courage. Amen.`,
  },
  {
    id: "shm-np-2",
    novenaId: "novenas-holy-martyrs",
    title: "Day 2 — The Faithful Unto Death",
    category: "novenas",
    day: 2,
    intention: "For fidelity to Christ unto the end",
    text: `O Holy Martyrs, you who were faithful unto death and received the crown of life that the Lord has promised to those who love Him, intercede for me today. Your faithfulness was not the result of your own strength, but of the grace of God working in your weakness. You were ordinary men and women — soldiers, mothers, children, slaves, nobles — who were made extraordinary by the power of the Holy Spirit. I ask you today to pray that I may be faithful to Christ in all the circumstances of my life. When I am tempted to compromise my faith, give me the strength to stand firm. When I am tempted to deny Christ through silence or cowardice, give me the courage to profess Him openly. When I am tempted to despair of God's mercy, remind me that the martyrs were sinners too, saved by the Blood of the Lamb. O Holy Martyrs, obtain for me the grace of final perseverance. Amen.`,
  },
  {
    id: "shm-np-3",
    novenaId: "novenas-holy-martyrs",
    title: "Day 3 — Joy in Suffering",
    category: "novenas",
    day: 3,
    intention: "To find joy in union with the suffering Christ",
    text: `O Holy Martyrs, you who rejoiced in your sufferings, counting it a privilege to suffer for the name of Jesus, teach me the mystery of redemptive joy. The apostles "rejoiced that they were found worthy to suffer dishonor for the name." Stephen, the first martyr, saw heaven opened as the stones rained down upon him. Perpetua and Felicity embraced the beasts with peace in their hearts. Your joy was not masochism or insanity; it was the supernatural joy of the Holy Spirit, who filled you with the certainty that your suffering had meaning and that your reward was eternal. I ask you today to help me find joy in my own sufferings — not the joy of pain itself, but the joy of union with Christ, who suffered for love of me. Help me to offer my crosses with gratitude, knowing that they have redemptive power when united to the Cross of Jesus. O Holy Martyrs, who rejoiced in suffering, teach me the secret of redemptive joy. Amen.`,
  },
  {
    id: "shm-np-4",
    novenaId: "novenas-holy-martyrs",
    title: "Day 4 — Love Stronger Than Death",
    category: "novenas",
    day: 4,
    intention: "To love God above all things",
    text: `O Holy Martyrs, you who loved God more than life itself, intercede for me today. Your love was not mere sentiment; it was a love proven by sacrifice, a love that would not surrender even in the face of the most terrible tortures. You loved God with all your heart, all your soul, all your mind, and all your strength — and you proved it by laying down your lives for the One who first loved you. I ask you today to inflame my heart with a similar love. Help me to love God above my own comfort, above my reputation, above my possessions, above my very life. Help me to love Him not only in the moments of consolation, but especially in the moments of trial, when love is tested and proven. O Holy Martyrs, whose love was stronger than death, obtain for me a heart that loves God above all things. Amen.`,
  },
  {
    id: "shm-np-5",
    novenaId: "novenas-holy-martyrs",
    title: "Day 5 — The Witness of Blood",
    category: "novenas",
    day: 5,
    intention: "For the persecuted Church throughout the world",
    text: `O Holy Martyrs, you who shed your blood for Christ in the persecutions of the Roman Empire, intercede today for all who are persecuted for the faith in our own time. Christians are being martyred in the Middle East, in Africa, in Asia, in many parts of the world. They suffer imprisonment, torture, displacement, and death for no other crime than confessing the name of Jesus. I pray for them today with all my heart. Protect them, strengthen them, comfort them, and give them the same courage that sustained you in your own martyrdom. Convert their persecutors, as You converted Saul on the road to Damascus. And grant to the whole Church the grace to stand in solidarity with our suffering brothers and sisters, to pray for them, to support them, and to be inspired by their witness. O Holy Martyrs, patrons of the persecuted, hear our prayer for the Church that suffers. Amen.`,
  },
  {
    id: "shm-np-6",
    novenaId: "novenas-holy-martyrs",
    title: "Day 6 — The White Martyrdom",
    category: "novenas",
    day: 6,
    intention: "To embrace the daily martyrdom of Christian life",
    text: `O Holy Martyrs, you who bore the red martyrdom of blood, teach me also the white martyrdom of daily sacrifice. Not all Christians are called to die for Christ, but all are called to die to themselves — to die to pride, to selfishness, to sensual desires, to the will that rebels against God. This daily dying is a kind of martyrdom that is lived in the quiet of the home, the workplace, the parish, the family. It is the martyrdom of patience with difficult people, of forgiveness when wronged, of generosity when resources are scarce, of fidelity when the heart is weary. I ask you today to help me embrace this white martyrdom with the same courage and love with which you embraced your red martyrdom. Help me to die to myself each day, so that Christ may live in me. O Holy Martyrs, obtain for me the grace of daily self-sacrifice. Amen.`,
  },
  {
    id: "shm-np-7",
    novenaId: "novenas-holy-martyrs",
    title: "Day 7 — The Martyrs and the Eucharist",
    category: "novenas",
    day: 7,
    intention: "For a deeper love of the Holy Eucharist",
    text: `O Holy Martyrs, many of you received the Body and Blood of Christ in the catacombs and hiding places, knowing that it might be your last communion before death. The Eucharist was the strength that sustained you, the food that nourished your courage, the guarantee of the resurrection that awaited you. You understood what many Catholics today forget: that the Mass is the most powerful reality on earth, and that Holy Communion is the greatest source of grace available to the human soul. I pray today for a deeper love of the Holy Eucharist in my own life. Help me to approach the altar with the same reverence, gratitude, and love with which you approached it in the face of death. Help me to receive Holy Communion with a heart purified by the Sacrament of Confession, and to carry the presence of Christ from the altar into every moment of my day. O Holy Martyrs, who died nourished by the Eucharist, renew my love for this heavenly Bread. Amen.`,
  },
  {
    id: "shm-np-8",
    novenaId: "novenas-holy-martyrs",
    title: "Day 8 — Intercession for the Dying",
    category: "novenas",
    day: 8,
    intention: "For a holy and peaceful death",
    text: `O Holy Martyrs, you who faced death with extraordinary courage and peace, intercede for all who are dying today. You knew that death was not the end but the doorway to eternal life, and this knowledge gave you the strength to face the executioner without fear. I pray today for all who are approaching death — the terminally ill, the elderly, those in danger of sudden death, and all who will die today. Grant them the grace of final perseverance, the protection of the holy angels, and the consolation of the sacraments. Help them to die in the state of grace, with faith, hope, and love burning in their hearts. Give their loved ones the courage to let them go and the confidence that they will meet again in heaven. O Holy Martyrs, who died as heroes of faith, pray for us now and at the hour of our death. Amen.`,
  },
  {
    id: "shm-np-9",
    novenaId: "novenas-holy-martyrs",
    title: "Day 9 — The Reward of the Martyrs",
    category: "novenas",
    day: 9,
    intention: "To persevere in faith to receive the eternal crown",
    text: `O glorious Holy Martyrs of Christ, on this final day of my novena, I honor your sacrifice and ask for your powerful intercession. You who fought the good fight, finished the race, and kept the faith, now wear the imperishable crown of righteousness that the righteous Judge has prepared for those who love His appearing. I pray that I may follow your example of courageous faithfulness, even if my own martyrdom takes the quieter form of daily self-denial and humble service. Help me to keep my eyes fixed on the prize — the eternal reward that awaits those who persevere to the end. When the trials of this life threaten to overwhelm me, remind me that they are temporary, but your reward is eternal. When I am tempted to give up, remind me that the martyrs endured far worse and did not surrender. O Holy Martyrs, who stand before the throne of God, pray for us now and always. Amen.`,
  },

  // NOVENA TO SAINT HELENA
  // novenaId: "novenas-saint-helen"

  {
    id: "sth-np-1",
    novenaId: "novenas-saint-helen",
    title: "Day 1 — The Pilgrim Empress",
    category: "novenas",
    day: 1,
    intention: "To begin a pilgrimage of faith",
    text: `O glorious Saint Helena, Empress of Rome, mother of Constantine the Great, and discoverer of the True Cross, intercede for me today. You who left the splendor of the imperial court to undertake a pilgrimage to the Holy Land, seeking the most sacred relic of the Christian faith, are the model of all pilgrims. Your journey was not merely a physical expedition; it was a spiritual quest, driven by a heart that longed to find the Cross of Christ. I pray today that I may begin my own pilgrimage of faith with the same zeal and determination. Help me to seek God not in the comforts of my routine, but in the sacred places where He has revealed Himself — in Scripture, in the sacraments, in the lives of the saints, in the faces of the poor. O Helena, pilgrim of faith, guide me on the path that leads to Christ. Amen.`,
  },
  {
    id: "sth-np-2",
    novenaId: "novenas-saint-helen",
    title: "Day 2 — The Finding of the True Cross",
    category: "novenas",
    day: 2,
    intention: "To discover the power of the Cross in my life",
    text: `O Saint Helena, you who discovered the True Cross of our Lord Jesus Christ beneath the Temple of Venus in Jerusalem, pray for me today. After years of searching, you unearthed three crosses from the hill of Golgotha, and through the healing of a deceased woman who was restored to life when touched by the True Cross, you identified the instrument of our salvation. I ask you today to help me discover the power of the Cross in my own life. Too often I carry my cross reluctantly, or try to set it aside entirely. Help me to recognize that the Cross is not merely a symbol of suffering, but the greatest expression of God's love — the means by which death was conquered and heaven was opened. Let me embrace my crosses with faith, knowing that they unite me to Christ and have redemptive power. O Helena, who found the hidden Cross, help me to discover its saving power. Amen.`,
  },
  {
    id: "sth-np-3",
    novenaId: "novenas-saint-helen",
    title: "Day 3 — The Faith of a Mother",
    category: "novenas",
    day: 3,
    intention: "For mothers and their spiritual influence",
    text: `O Saint Helena, you were not only an empress and a pilgrim, but above all a mother. It was your faith that influenced your son Constantine to legalize Christianity and transform the Roman Empire. Your example of piety, charity, and devotion to the Cross shaped the destiny of Western civilization. I pray today for all mothers, that they may have the same spiritual influence over their children. Give them the grace to transmit the faith not only by words but by example, to teach their children to love God, to pray, and to live according to the Gospel. I pray also for those mothers who have lost their children to the faith, who weep and pray without ceasing for their return. Console them with the hope that their prayers, like yours, will bear fruit in God's perfect timing. O Helena, model of holy motherhood, intercede for all mothers today. Amen.`,
  },
  {
    id: "sth-np-4",
    novenaId: "novenas-saint-helen",
    title: "Day 4 — The Holy Places of Jerusalem",
    category: "novenas",
    day: 4,
    intention: "To venerate the sacred places of our redemption",
    text: `O Saint Helena, you who walked the very streets where Christ walked, who knelt at the site of His birth, who prayed at the place of His death and the tomb of His burial, intercede for me today. You built churches over the holy places — the Church of the Nativity in Bethlehem, the Church of the Holy Sepulchre in Jerusalem — preserving them for future generations so that the faithful might make pilgrimage and deepen their devotion. I pray today for a deeper reverence for the sacred places of our faith. Help me to approach the church where I worship with the same awe with which you approached the holy sites of Jerusalem. Help me to see in every parish church a piece of heaven, in every tabernacle the presence of the living God, and in every altar the place where Calvary is made present. O Helena, builder of holy places, help me to reverence the sacred spaces of our faith. Amen.`,
  },
  {
    id: "sth-np-5",
    novenaId: "novenas-saint-helen",
    title: "Day 5 — The Royal Cross",
    category: "novenas",
    day: 5,
    intention: "To honor the Cross of Christ as the symbol of our faith",
    text: `O Saint Helena, you adorned the True Cross with gold and precious gems, making it the most revered relic in Christendom. You understood that the Cross, once an instrument of shame, had become the throne of glory, the royal standard of the King of Kings. I pray today for a deeper love and reverence for the Holy Cross. Help me to wear it with pride, to venerate it with devotion, and to honor it not merely as jewelry or decoration, but as the supreme symbol of God's love and the instrument of my salvation. When I look upon the Cross, help me to see not just a piece of wood, but the altar where the Lamb of God was sacrificed for the sins of the world. Let the Cross be the center of my spiritual life, the source of my hope, and the sign of my identity as a Christian. O Helena, who crowned the Cross with glory, help me to honor it with my life. Amen.`,
  },
  {
    id: "sth-np-6",
    novenaId: "novenas-saint-helen",
    title: "Day 6 — Conversion of the Emperor",
    category: "novenas",
    day: 6,
    intention: "For the conversion of world leaders",
    text: `O Saint Helena, your son Constantine saw the sign of the Cross in the sky before the Battle of the Milvian Bridge and heard the words: "In this sign you will conquer." Through your influence and through the power of this divine sign, the Roman Empire was transformed from the greatest persecutor of Christians into the greatest patron of the Church. I pray today for the conversion of world leaders — presidents, prime ministers, kings, and those in positions of power. Open their eyes to the sign of the Cross. Give them the courage to govern according to the principles of justice, truth, and the dignity of the human person. Convert those who persecute the Church, protect those who defend the faith, and inspire all leaders to use their authority for the common good and the glory of God. O Helena, mother of an emperor, intercede for the rulers of our time. Amen.`,
  },
  {
    id: "sth-np-7",
    novenaId: "novenas-saint-helen",
    title: "Day 7 — Generosity and Charity",
    category: "novenas",
    day: 7,
    intention: "To practice Christian charity and generosity",
    text: `O Saint Helena, you who used your imperial wealth and power to build churches, support the poor, and honor the relics of the faith, teach me the virtue of holy generosity. You distributed alms lavishly, adorned the churches with treasures, and used your influence to advance the cause of the Gospel. You understood that the wealth and power God had given you were not yours to hoard, but gifts to be used for the greater glory of God and the good of the Church. I pray today for the grace of generous stewardship. Help me to use whatever gifts I have — time, talent, treasure, influence — for the service of God and neighbor. Remove from my heart the hoarding spirit that clings to possessions, the fear that prevents me from giving, and the selfishness that keeps my resources for myself alone. O Helena, model of holy generosity, teach me to give as God has given to me. Amen.`,
  },
  {
    id: "sth-np-8",
    novenaId: "novenas-saint-helen",
    title: "Day 8 — The Cross and the Church",
    category: "novenas",
    day: 8,
    intention: "For unity in the Church under the sign of the Cross",
    text: `O Saint Helena, you who labored to unite the Church under the sign of the Cross, intercede for the unity of Christians today. The Cross of Christ is the sign of our redemption and the symbol of our unity — for there is one Cross, one Lord, one faith, one baptism. Yet the Church remains divided, and Christians are separated from one another by centuries of misunderstanding, polemics, and sin. I pray today for the healing of these divisions. Grant to the leaders of the Church the wisdom and humility to seek unity in truth and charity. Help me to do my part — to pray for Christian unity, to live my faith with integrity, and to treat all baptized Christians with the respect and love they deserve as brothers and sisters in Christ. O Helena, who honored the Cross that unites all Christians, pray for the visible unity of Christ's Body on earth. Amen.`,
  },
  {
    id: "sth-np-9",
    novenaId: "novenas-saint-helen",
    title: "Day 9 — The Eternal Pilgrimage",
    category: "novenas",
    day: 9,
    intention: "To continue the pilgrimage of faith to heaven",
    text: `O glorious Saint Helena, Empress and Pilgrim, on this final day of my novena, I ask for your powerful intercession. You spent your final years in prayer and good works, distributing your wealth to the poor, building churches, and preparing your soul for the eternal encounter with the Lord. You died in peace, having found what you sought — the True Cross of Christ — and having given your life in service to the One who died upon it. I pray today that I may continue my pilgrimage of faith with the same devotion and generosity. Help me to keep my eyes fixed on heaven, the ultimate destination of every Christian soul. Help me to walk the path of faith with perseverance, to venerate the Cross with love, and to arrive at last in the heavenly Jerusalem, where I hope to see you, dear Saint Helena, and to thank you for your prayers. O Helena, pilgrim of heaven, guide me safely to my eternal home. Amen.`,
  },

  // NOVENA TO SAINTS JOACHIM AND ANNE
  // novenaId: "novenas-saint-joachim-anne"

  {
    id: "sja-np-1",
    novenaId: "novenas-saint-joachim-anne",
    title: "Day 1 — The Holy Parents of Mary",
    category: "novenas",
    day: 1,
    intention: "To honor the parents of the Blessed Virgin Mary",
    text: `O glorious Saints Joachim and Anne, parents of the Blessed Virgin Mary and grandparents of Jesus Christ, intercede for me today. You were chosen by God from all eternity to be the earthly parents of the Mother of God — a privilege beyond all human understanding. You lived in the Temple for many years, praying for the coming of the Messiah, and God heard your prayers by giving you a daughter who would become the living Ark of the Covenant. I honor you today as the holy couple through whom the Savior entered the world. Help me to understand the sacred dignity of my own family life, my own parenthood, my own grandparenthood, and to live it with the same faith and devotion that characterized your holy household. O Joachim and Anne, parents of Mary, bless all families today. Amen.`,
  },
  {
    id: "sja-np-2",
    novenaId: "novenas-saint-joachim-anne",
    title: "Day 2 — The Gift of Infertility",
    category: "novenas",
    day: 2,
    intention: "For couples struggling with infertility",
    text: `O Saints Joachim and Anne, you know the deep sorrow of childlessness in a culture that valued children as a sign of God's blessing. For years you prayed for a child, and your prayers seemed to go unanswered. Yet God was preparing something far greater than you could have imagined — a daughter who would become the Mother of the Savior. I pray today for all couples who struggle with the pain of infertility. Comfort them in their sorrow, strengthen their marriage in this trial, and grant them the grace to trust in God's providence. If it is God's will, bless them with the gift of a child. If not, help them to find meaning and purpose in other ways of serving God and His Church. Remind them that their worth is not determined by their fertility, but by their identity as beloved children of God. O Joachim and Anne, who suffered and were blessed, comfort all who suffer the cross of infertility. Amen.`,
  },
  {
    id: "sja-np-3",
    novenaId: "novenas-saint-joachim-anne",
    title: "Day 3 — Raising the Mother of God",
    category: "novenas",
    day: 3,
    intention: "For parents raising children in the faith",
    text: `O Saints Joachim and Anne, you had the extraordinary privilege and responsibility of raising the Immaculate Conception — the one human being conceived without original sin, the future Mother of God. You taught her to pray, to read the Scriptures, to love God above all things, and to prepare herself for the great vocation that awaited her. I pray today for all parents who are raising children in the faith. This is a sacred task, perhaps the most important work in the world — forming the souls of the next generation. Give parents the wisdom to teach their children the faith with love and consistency. Give them the patience to endure the difficulties of parenthood. Give them the example of holiness that their children need to see. Help them to understand that every bedtime prayer, every family rosary, every act of sacrificial love is shaping the souls of saints. O Joachim and Anne, model parents, bless all who raise children today. Amen.`,
  },
  {
    id: "sja-np-4",
    novenaId: "novenas-saint-joachim-anne",
    title: "Day 4 — The Dignity of Grandparents",
    category: "novenas",
    day: 4,
    intention: "For the role of grandparents in the family",
    text: `O Saints Joachim and Anne, you are the patrons of grandparents, and I honor you today for the sacred role that grandparents play in the life of the family. You were the grandparents of Jesus Christ — the earthly grandparents of God made flesh. This dignity alone makes grandparenthood a holy vocation. I pray today for all grandparents: for those who are actively involved in the lives of their grandchildren, for those who are separated from them by distance or circumstance, for those who are raising grandchildren due to the illness or incapacity of their own children, and for those who have been called home to God and whose grandchildren miss them deeply. Help grandparents to transmit the faith to the younger generation, to tell the stories of God's faithfulness, to model holiness in the autumn of life, and to pray faithfully for their grandchildren. O Joachim and Anne, holy grandparents, bless all grandparents with your intercession. Amen.`,
  },
  {
    id: "sja-np-5",
    novenaId: "novenas-saint-joachim-anne",
    title: "Day 5 — Faith in Silence",
    category: "novenas",
    day: 5,
    intention: "To trust God in seasons of waiting",
    text: `O Saints Joachim and Anne, you waited many years for the child God had promised you. Your waiting was not passive; it was a living faith that continued to pray, to hope, and to serve God even when the years passed without an answer. You trusted that God's timing was perfect, that He who had promised would also fulfill. I pray today for the grace to trust God in seasons of waiting — when prayers seem unanswered, when hopes are delayed, when the future is uncertain. Help me to believe that God is always at work, even when I cannot see His hand. Help me to wait with patience and faith, knowing that God's delays are not denials, and that He is preparing something beautiful in His own time. O Joachim and Anne, who waited in faith and were blessed beyond measure, teach me to wait on the Lord with confidence and hope. Amen.`,
  },
  {
    id: "sja-np-6",
    novenaId: "novenas-saint-joachim-anne",
    title: "Day 6 — The Holy Family",
    category: "novenas",
    day: 6,
    intention: "For the sanctity of family life",
    text: `O Saints Joachim and Anne, you formed the beginning of the Holy Family — the most perfect family in the history of the world. Through your daughter Mary and her husband Joseph, the Word became flesh and dwelt among us. Your home in Nazareth was a place of faith, love, prayer, and holiness. I pray today for the sanctity of family life in our world. The family is under attack from many forces — secularism, materialism, divorce, abuse, and the breakdown of traditional values. Strengthen families today, O Lord. Help husbands and wives to love each other as Christ loved the Church. Help parents to raise their children in the faith. Help children to honor and obey their parents. Help grandparents to be sources of wisdom and grace. Let every Christian home become a domestic church where God is honored and His love is lived. O Joachim and Anne, models of family holiness, bless all families today. Amen.`,
  },
  {
    id: "sja-np-7",
    novenaId: "novenas-saint-joachim-anne",
    title: "Day 7 — Devotion to the Presentation",
    category: "novenas",
    day: 7,
    intention: "To present my life to God in service",
    text: `O Saints Joachim and Anne, according to the ancient tradition, you presented your daughter Mary to the Temple at the age of three, dedicating her to the service of God. This act of faith and generosity was the beginning of the great mystery of our redemption. You gave to God the greatest gift you had — your only child — and God gave her back to you and to the world as the Mother of the Savior. I pray today that I may present my own life to God in the same spirit of faith and generosity. Whatever I have — my time, my talents, my relationships, my possessions — all belong to God and are meant to be used for His glory. Help me to offer them without reservation, without calculation, without fear. O Joachim and Anne, who presented Mary to God, help me to present my life as a living sacrifice, holy and pleasing to God. Amen.`,
  },
  {
    id: "sja-np-8",
    novenaId: "novenas-saint-joachim-anne",
    title: "Day 8 — The Ancestors of Christ",
    category: "novenas",
    day: 8,
    intention: "To honor my own spiritual ancestors",
    text: `O Saints Joachim and Anne, you were the ancestors of Christ according to the flesh, the earthly roots of the divine family tree. You stand in the great lineage of the holy men and women who prepared the way for the coming of the Savior. I pray today that I may honor my own spiritual ancestors — the saints who have gone before me, the faithful Christians who passed on the faith through the centuries, the parents and grandparents who taught me to pray, and the catechists and teachers who formed me in the faith. I am part of a great communion of saints, a vast family that spans all ages and all lands. Help me to live in a way that is worthy of this heritage, and to pass on the faith to the next generation with the same love and devotion with which it was passed on to me. O Joachim and Anne, ancestors of Christ, help me to honor my spiritual heritage. Amen.`,
  },
  {
    id: "sja-np-9",
    novenaId: "novenas-saint-joachim-anne",
    title: "Day 9 — The Eternal Reunion",
    category: "novenas",
    day: 9,
    intention: "To hope in the eternal reunion of families in heaven",
    text: `O glorious Saints Joachim and Anne, on this final day of my novena, I entrust to your intercession my family — living and departed. You who were reunited with your daughter Mary in the glory of heaven, pray that my family may one day be reunited in the heavenly homeland. For those family members who have died, I pray that they may be enjoying the peace of heaven. For those who are living, I pray that we may grow together in faith, love, and holiness, so that our earthly family may become an image of the heavenly family, where God is Father, Mary is Mother, and all the saints are brothers and sisters. Help me to live each day in a way that prepares me and my family for the eternal joy of heaven. O Saints Joachim and Anne, holy parents and grandparents, intercede for my family now and at the hour of our death. Amen.`,
  },

  // NOVENA TO SAINT MATTHEW
  // novenaId: "novenas-saint-matthew"

  {
    id: "smt-np-1",
    novenaId: "novenas-saint-matthew",
    title: "Day 1 — The Call of the Tax Collector",
    category: "novenas",
    day: 1,
    intention: "For the grace to respond immediately to Christ's call",
    text: `O glorious Saint Matthew, Apostle and Evangelist, you who were called by Christ while sitting at the tax collector's booth, intercede for me today. You were a man despised by your own people — a tax collector who collaborated with the Roman occupiers and enriched himself at the expense of the poor. Yet when Jesus looked at you with those eyes of mercy and said simply, "Follow me," you rose without hesitation and left everything behind. What a testimony to the power of Christ's call and the transforming grace of conversion! I pray today that I may respond to the call of Christ with the same immediacy and generosity. Whatever my past, whatever my sins, whatever my limitations — when Christ calls, I will follow. O Matthew, who left all to follow Jesus, obtain for me the grace of immediate and generous response to God's call. Amen.`,
  },
  {
    id: "smt-np-2",
    novenaId: "novenas-saint-matthew",
    title: "Day 2 — The Conversion of Sinners",
    category: "novenas",
    day: 2,
    intention: "For the conversion of all sinners, especially those far from God",
    text: `O Saint Matthew, you know from your own experience the joy of conversion — the overwhelming gratitude of a sinner who has been forgiven. After your call, you invited Jesus to a great banquet in your home, and the Pharisees complained: "Why does your teacher eat with tax collectors and sinners?" Jesus answered: "It is not the healthy who need a physician, but the sick. I have not come to call the righteous, but sinners." I pray today for all sinners who are far from the Church — those who have left the practice of the faith, those who live in grave sin, those who have never known the mercy of God. Touch their hearts, Lord, as You touched Matthew's heart. Call them by name, as You called Matthew. Lead them to repentance, to confession, to a new life in Christ. O Matthew, patron of conversions, intercede for all who need to return to God. Amen.`,
  },
  {
    id: "smt-np-3",
    novenaId: "novenas-saint-matthew",
    title: "Day 3 — Wealth and Poverty",
    category: "novenas",
    day: 3,
    intention: "To use wealth rightly for God's glory",
    text: `O Saint Matthew, you who were a wealthy man before your conversion, and who used your wealth to host a great banquet for Jesus and his disciples, teach me the proper use of material goods. Before your call, you hoarded wealth for yourself; after your call, you used it to honor Christ and serve his mission. I pray today that I may have a right relationship with money and possessions. Help me to be generous with what God has given me, to use my resources for the good of others and the glory of God, and to hold nothing back from the Lord. Free me from the love of money, the fear of poverty, and the temptation to trust in wealth rather than in God. O Matthew, who transformed your wealth into an instrument of hospitality and grace, help me to be a faithful steward of God's gifts. Amen.`,
  },
  {
    id: "smt-np-4",
    novenaId: "novenas-saint-matthew",
    title: "Day 4 — The Gospel of Matthew",
    category: "novenas",
    day: 4,
    intention: "To read and live the Gospel of Matthew",
    text: `O Saint Matthew, Evangelist and writer of the first Gospel, you who recorded the words and deeds of Christ for the benefit of all generations, intercede for me today. Your Gospel is the most quoted book of the New Testament, the foundation of Christian catechesis, and the bridge between the Old Testament and the New. You presented Jesus as the promised Messiah, the new Moses, the fulfiller of the Law and the Prophets. I pray today for a deeper love of your Gospel. Help me to read it not merely as a historical document, but as the living Word of God, addressed personally to me. Help me to hear in its pages the voice of Christ calling me to conversion, to faith, and to discipleship. O Matthew, whose Gospel has instructed the Church for two millennia, help me to read, to understand, and to live the Word of God. Amen.`,
  },
  {
    id: "smt-np-5",
    novenaId: "novenas-saint-matthew",
    title: "Day 5 — The Feast of Mercy",
    category: "novenas",
    day: 5,
    intention: "To celebrate God's boundless mercy",
    text: `O Saint Matthew, you who hosted the feast for Jesus and became the living proof of God's boundless mercy, intercede for me today. Your feast was not a quiet dinner; it was a celebration of mercy, a public testimony that no sinner is beyond the reach of God's love. The Pharisees could not understand it; the sinners flocked to it; Jesus was glorified in it. I pray today for a deeper appreciation of God's mercy in my own life. When I am tempted to despair of my sins, remind me that Jesus came not for the righteous but for sinners. When I am tempted to judge others, remind me that I too am in need of mercy. When I am tempted to give up on someone who seems beyond redemption, remind me of your own story. O Matthew, living proof of God's mercy, help me to trust in the inexhaustible mercy of the Father. Amen.`,
  },
  {
    id: "smt-np-6",
    novenaId: "novenas-saint-matthew",
    title: "Day 6 — Martyrdom for the Faith",
    category: "novenas",
    day: 6,
    intention: "For the courage to die for Christ if called",
    text: `O Saint Matthew, Apostle and Martyr, you who sealed your faith with your blood in Ethiopia, intercede for me today. After years of preaching the Gospel in distant lands, you were martyred for the faith, offering your life as the final act of love for the One who had called you from the tax collector's booth. You did not flinch from the ultimate sacrifice; you went to your death with the same courage with which you had left everything to follow Christ. I pray today for the courage to die for Christ if I am called to do so — whether in the dramatic form of martyrdom or in the quieter form of daily self-denial. Help me to live each day with the awareness that this life is a preparation for eternity, and that the ultimate question is not whether I have succeeded in the world's eyes, but whether I have been faithful to Christ. O Matthew, martyr and apostle, obtain for me the grace of holy courage. Amen.`,
  },
  {
    id: "smt-np-7",
    novenaId: "novenas-saint-matthew",
    title: "Day 7 — The Patron of Accountants and Financiers",
    category: "novenas",
    day: 7,
    intention: "For integrity in financial matters",
    text: `O Saint Matthew, patron of accountants, tax collectors, and financiers, you who transformed your life from the love of money to the love of God, intercede for all who work in the financial world today. In an age of economic uncertainty, corruption, and greed, the Church needs the witness of Catholics who work in finance with integrity, honesty, and generosity. I pray for all who handle money and accounts — that they may do so with the same sense of responsibility and justice that you practiced after your conversion. Help them to see their work not as a means of self-enrichment alone, but as a service to the common good, a way to support their families, and an opportunity to practice the virtues of stewardship and charity. O Matthew, who left the counting house to become an apostle, help all who work with money to do so for the glory of God. Amen.`,
  },
  {
    id: "smt-np-8",
    novenaId: "novenas-saint-matthew",
    title: "Day 8 — The Evangelist's Mission",
    category: "novenas",
    day: 8,
    intention: "To share the Gospel with those who have not heard it",
    text: `O Saint Matthew, Evangelist and missionary, you who carried the Gospel to the distant land of Ethiopia and proclaimed the good news of Jesus Christ to those who had never heard it, intercede for me today. Your Gospel was written for a specific audience — the Jewish community — but its message is universal. Through your inspired writing, the saving truth of Christ has reached every corner of the world. I pray today for the missionary work of the Church. Strengthen those who preach the Gospel in foreign lands. Bless the work of translators who make the Scriptures available in every language. Inspire missionaries to follow your example of courage and generosity. And help me, in my own way, to share the Gospel with those around me — my family, my friends, my neighbors, and all who are open to hearing the good news. O Matthew, evangelist and missionary, obtain for me the grace to be a faithful witness to the Gospel. Amen.`,
  },
  {
    id: "smt-np-9",
    novenaId: "novenas-saint-matthew",
    title: "Day 9 — The Apostle's Reward",
    category: "novenas",
    day: 9,
    intention: "To receive the reward of the faithful apostle",
    text: `O glorious Saint Matthew, Apostle and Evangelist, on this final day of my novena, I commend myself to your powerful intercession. You who were called from sin to grace, from wealth to poverty, from death to life, now stand in the presence of the Lord as a victorious apostle and a glorious saint. You who wrote the first Gospel, who preached in distant lands, who died for the faith, now enjoy the eternal reward that was promised to those who follow Christ. I pray today that I may live my life in such a way that I, too, will hear those blessed words: "Well done, good and faithful servant. Enter into the joy of your Lord." Help me to respond to God's call with the same generosity with which you responded. Help me to use my gifts for the glory of God and the good of souls. Help me to persevere in faith to the end, and to receive at last the crown of righteousness that awaits all the faithful. O Matthew, apostle and evangelist, pray for me now and at the hour of my death. Amen.`,
  },

  // NOVENA TO SAINT THOMAS THE APOSTLE
  // novenaId: "novenas-saint-thomas-apostle"

  {
    id: "stt-np-1",
    novenaId: "novenas-saint-thomas-apostle",
    title: "Day 1 — The Doubting Apostle",
    category: "novenas",
    day: 1,
    intention: "To bring my doubts to Christ with honesty",
    text: `O glorious Saint Thomas, Apostle of Christ and patron of those who struggle with doubt, intercede for me today. You are remembered as "Doubting Thomas," but your doubt was not a sign of weakness; it was the honest struggle of a mind that demanded truth and a heart that refused to settle for secondhand faith. When the other apostles told you they had seen the risen Lord, you declared with courageous honesty: "Unless I see the mark of the nails in his hands, and put my finger in the mark of the nails and my hand in his side, I will not believe." I pray today that I may have the same honesty with God. Help me to bring my doubts to Christ rather than away from Him, to seek truth with courage, and to trust that He who showed you His wounds will also show Himself to me. O Thomas, honest seeker, obtain for me the grace of honest faith. Amen.`,
  },
  {
    id: "stt-np-2",
    novenaId: "novenas-saint-thomas-apostle",
    title: "Day 2 — Faith Demanding Proof",
    category: "novenas",
    day: 2,
    intention: "To seek God with intellectual integrity",
    text: `O Saint Thomas, you who refused to believe without proof, intercede for all who struggle with intellectual doubt today. In an age of scientific materialism and relativism, many sincere seekers find it difficult to believe. They demand evidence, they question authority, they wrestle with the hard texts of Scripture, and they struggle to reconcile faith with reason. I pray for them today. Help them, as you were helped, to encounter the risen Christ in a way that satisfies their minds and transforms their hearts. Grant them the grace to see that faith is not the enemy of reason, but its fulfillment; that doubt, honestly wrestled with, can lead to a deeper faith; and that the God who created the human intellect will not ask it to believe what is unreasonable. O Thomas, who found proof in the wounds of Christ, help all who seek to believe. Amen.`,
  },
  {
    id: "stt-np-3",
    novenaId: "novenas-saint-thomas-apostle",
    title: "Day 3 — My Lord and My God",
    category: "novenas",
    day: 3,
    intention: "To make the profession of faith of Saint Thomas",
    text: `O Saint Thomas, when you finally saw the risen Christ standing before you, with the wounds still visible in His hands and side, you fell to your knees and made the most profound profession of faith in all of Scripture: "My Lord and my God!" These words are not merely an exclamation of surprise; they are the highest affirmation of the divinity of Christ ever spoken by human lips. I pray today that I may make this same profession with the fullness of my heart. When I see the wounds of Christ in the Eucharist, when I encounter His presence in the sacraments, when I recognize His hand at work in my life — help me to fall to my knees and proclaim: "My Lord and my God!" Let this be not only the words of my mouth but the confession of my life, that every thought, word, and deed may testify to the lordship of Jesus Christ. O Thomas, who proclaimed the divinity of Christ, help me to live that profession every day. Amen.`,
  },
  {
    id: "stt-np-4",
    novenaId: "novenas-saint-thomas-apostle",
    title: "Day 4 — The Courage to Touch Christ's Wounds",
    category: "novenas",
    day: 4,
    intention: "To not be afraid of the wounded Christ",
    text: `O Saint Thomas, Jesus invited you to touch His wounds — to put your finger in the nails and your hand in His side. This was not merely a proof of the resurrection; it was an invitation to intimacy with the suffering Christ. The wounds of Jesus are not something to avoid or fear; they are the doors through which we enter into the mystery of God's love. I pray today for the courage to touch the wounds of Christ — to not turn away from suffering, whether my own or that of others. Help me to see in every wound the love of the One who was wounded for our sake. Help me to approach the broken with tenderness, the suffering with compassion, and the dying with hope. O Thomas, who touched the wounds of Christ, teach me not to fear the wounds of my brothers and sisters. Amen.`,
  },
  {
    id: "stt-np-5",
    novenaId: "novenas-saint-thomas-apostle",
    title: "Day 5 — The Mission to India",
    category: "novenas",
    day: 5,
    intention: "For the courage to go where God sends me",
    text: `O Saint Thomas, you who carried the Gospel to the distant shores of India and established the Christian community there that endures to this day, intercede for me today. You left the familiar surroundings of Palestine and traveled to a land utterly foreign to you — a land of different languages, different customs, different religions. Yet you went in faith, trusting that the Lord who called you would also guide and protect you. I pray today for the courage to go where God sends me — whether to a foreign land or to the difficult neighborhood next door, whether to a new ministry or a new conversation, whether across the ocean or across the street. Help me to leave my comfort zone, to trust in God's providence, and to bring the light of Christ wherever I go. O Thomas, apostle of India, obtain for me the grace of missionary courage. Amen.`,
  },
  {
    id: "stt-np-6",
    novenaId: "novenas-saint-thomas-apostle",
    title: "Day 6 — Martyrdom at Madras",
    category: "novenas",
    day: 6,
    intention: "For the grace to suffer for Christ with courage",
    text: `O Saint Thomas, according to ancient tradition, you were martyred near Madras in India, pierced with a spear while praying at a hilltop chapel. You who had demanded proof of the resurrection, sealed your own faith with the supreme proof of martyrdom. You did not hesitate to give your life for the One whose wounds you had once refused to believe. I pray today for the courage to suffer for Christ — whether in the dramatic form of martyrdom or in the quieter forms of daily self-denial, ridicule, and rejection. Help me to remember that the martyrs were not superhuman; they were ordinary people who were filled with extraordinary grace. Give me the same grace, so that when the moment of testing comes, I may stand firm in my faith and bear witness to the truth with my life. O Thomas, martyr and apostle, obtain for me the grace of holy courage. Amen.`,
  },
  {
    id: "stt-np-7",
    novenaId: "novenas-saint-thomas-apostle",
    title: "Day 7 — The Apostle of the Doubtful",
    category: "novenas",
    day: 7,
    intention: "For those who are struggling with faith",
    text: `O Saint Thomas, you are the patron of all who struggle with doubt, and I bring before you today all who are experiencing crisis of faith. There are many in our time who have lost their faith, who are wavering in their commitment, who are tempted to abandon the Church or to give up on God altogether. Some have been hurt by the Church; others have been scandalized by the behavior of Christians; still others have simply drifted away through neglect. I pray for each one of them by name, though I do not know their names — only God does. Touch their hearts, Lord, as You touched the heart of Thomas. Show them Your wounds, as You showed them to Thomas. Let them hear Your voice speaking their name, as Thomas heard his. And bring them home to the faith, to the sacraments, to the community of the Church. O Thomas, patron of the doubtful, intercede for all who struggle to believe. Amen.`,
  },
  {
    id: "stt-np-8",
    novenaId: "novenas-saint-thomas-apostle",
    title: "Day 8 — The Liturgy of Thomas Christians",
    category: "novenas",
    day: 8,
    intention: "To honor the ancient liturgical traditions of the Church",
    text: `O Saint Thomas, the Christians of India who trace their faith to your apostolic preaching have preserved one of the most ancient and beautiful liturgical traditions in the Church — the Syro-Malabar and Syro-Malankara liturgies, which connect us to the earliest worship of the Christian community. I pray today for the preservation and renewal of these ancient traditions, and for all the Eastern Catholic Churches that maintain the richness of the early Church's worship. Help me to appreciate the diversity of the Church's liturgical traditions and to recognize that there is one faith expressed in many legitimate forms of worship. Grant to the whole Church the grace to honor its ancient liturgical heritage while faithfully responding to the needs of the present age. O Thomas, father of the Indian Christians, bless and protect your spiritual children today. Amen.`,
  },
  {
    id: "stt-np-9",
    novenaId: "novenas-saint-thomas-apostle",
    title: "Day 9 — From Doubt to Glory",
    category: "novenas",
    day: 9,
    intention: "To journey from doubt to unshakable faith",
    text: `O glorious Saint Thomas, Apostle of Christ, on this final day of my novena, I honor your journey from doubt to glory. You began as an honest skeptic, a man who refused to believe without proof. You encountered the risen Christ, and your doubt was transformed into the most profound profession of faith. You carried the Gospel to the ends of the earth, and you sealed your apostleship with your blood. Your journey is the journey of every Christian — from doubt to faith, from fear to courage, from death to resurrection. I pray today that I may follow this same path. When doubt assails me, help me to bring it honestly to Christ. When fear grips me, help me to trust in the risen Lord. When death approaches, help me to proclaim with you: "My Lord and my God!" O Thomas, whose doubt became glory, pray for me now and always. Amen.`,
  },

  // NOVENA TO SAINT LUKE
  // novenaId: "novenas-saint-luke"

  {
    id: "slk-np-1",
    novenaId: "novenas-saint-luke",
    title: "Day 1 — The Beloved Physician",
    category: "novenas",
    day: 1,
    intention: "For doctors, nurses, and all who heal",
    text: `O glorious Saint Luke, Evangelist and beloved physician, patron of doctors and healers, intercede for me today. You were a man of science and a man of faith — a physician who healed bodies and an evangelist who healed souls. Saint Paul called you "the beloved physician," and your Gospel is the most comprehensive and historically detailed account of the life of Christ. I pray today for all who work in the healing professions — doctors, nurses, pharmacists, therapists, counselors, and all who tend to the sick. Give them the skill to heal, the compassion to comfort, the wisdom to discern, and the faith to trust in the divine Physician. Help them to see in every patient the face of Christ, and to serve with the same love and dedication that characterized your own ministry. O Luke, physician and evangelist, bless all who bring healing to the sick. Amen.`,
  },
  {
    id: "slk-np-2",
    novenaId: "novenas-saint-luke",
    title: "Day 2 — The Gospel of Mercy",
    category: "novenas",
    day: 2,
    intention: "To encounter the mercy of God in Luke's Gospel",
    text: `O Saint Luke, your Gospel is often called the Gospel of Mercy, for you alone recorded many of the most beautiful parables of divine mercy — the Good Samaritan, the Lost Sheep, the Prodigal Son, the Pharisee and the Tax Collector. You understood, perhaps better than any other evangelist, the infinite mercy of God for sinners. I pray today that I may encounter this mercy in the pages of your Gospel. Help me to read again the story of the Prodigal Son and to see myself in the younger son who returned home in shame, and in the father who ran to meet him with open arms. Help me to know that no matter how far I have wandered, God's mercy is always greater than my sin. O Luke, evangelist of mercy, open my eyes to the boundless compassion of the Father. Amen.`,
  },
  {
    id: "slk-np-3",
    novenaId: "novenas-saint-luke",
    title: "Day 3 — The Companion of Saint Paul",
    category: "novenas",
    day: 3,
    intention: "For faithful companionship in the work of evangelization",
    text: `O Saint Luke, you who accompanied Saint Paul on his missionary journeys — through storms, shipwrecks, imprisonments, and persecutions — intercede for me today. You were not merely a traveling companion; you were a co-worker, a fellow evangelist, a brother in the faith. When Paul was in prison, you were there. When Paul was shipwrecked, you were there. When Paul was writing his epistles, you were there, taking notes, organizing, serving. I pray today for faithful companions in the work of evangelization. Help me to find brothers and sisters in Christ who will walk with me in the journey of faith, who will support me in trials, who will encourage me in discouragement, and who will share the work of the Gospel with me. And help me to be such a companion for others — loyal, generous, and faithful to the end. O Luke, faithful companion of Paul, teach me the beauty of Christian fellowship. Amen.`,
  },
  {
    id: "slk-np-4",
    novenaId: "novenas-saint-luke",
    title: "Day 4 — The Artist and Iconographer",
    category: "novenas",
    day: 4,
    intention: "For artists, painters, and all who create beauty",
    text: `O Saint Luke, you are traditionally regarded as the first iconographer — the one who painted the image of the Blessed Virgin Mary, creating the first sacred image in Christian history. The Eastern Church honors you as the patron of painters and artists, and your icons have inspired devotion for centuries. I pray today for all artists — painters, sculptors, musicians, writers, actors, and all who create beauty. Help them to use their gifts for the glory of God and the edification of the Church. Inspire them to create works that elevate the human spirit, that reveal the beauty of truth, and that draw hearts to the beauty of God. In a world that often celebrates ugliness and vulgarity, raise up artists who will restore the tradition of sacred art that lifts the soul to heaven. O Luke, patron of artists, bless all who create beauty in God's name. Amen.`,
  },
  {
    id: "slk-np-5",
    novenaId: "novenas-saint-luke",
    title: "Day 5 — The Acts of the Apostles",
    category: "novenas",
    day: 5,
    intention: "For the renewal of the Church in our time",
    text: `O Saint Luke, author of the Acts of the Apostles, you recorded the history of the early Church with vivid detail and inspired insight. In the Acts, we see the Holy Spirit descending at Pentecost, the apostles preaching with boldness, the community sharing all things in common, and the Church growing from a small group of frightened disciples into a worldwide movement that transformed the Roman Empire. I pray today for a new Pentecost in the Church. Send the Holy Spirit upon the Church in our time, as You sent Him upon the apostles at Jerusalem. Renew the gifts of the Spirit, restore the zeal of the early Church, and inspire a new generation of Christians to live with the same courage, generosity, and joy that characterized the first disciples. O Luke, historian of the early Church, intercede for the renewal of the Church today. Amen.`,
  },
  {
    id: "slk-np-6",
    novenaId: "novenas-saint-luke",
    title: "Day 6 — The Physician of the Soul",
    category: "novenas",
    day: 6,
    intention: "For spiritual healing and inner peace",
    text: `O Saint Luke, you who healed bodies as a physician and souls as an evangelist, intercede for me today. I need healing — not only in body, but in soul. There are wounds that no human doctor can heal: the wounds of sin, the scars of past trauma, the hurts of broken relationships, the loneliness of the human heart. You understand this, because you served a Lord who was himself the divine Physician — the one who said, "It is not the healthy who need a physician, but the sick." I bring my wounds to you today, dear saint. Touch the places in my heart that are broken. Heal the memories that haunt me. Restore the relationships that have been damaged. And lead me to the great Physician, Jesus Christ, who alone can make me whole. O Luke, physician of body and soul, obtain for me the healing I need. Amen.`,
  },
  {
    id: "slk-np-7",
    novenaId: "novenas-saint-luke",
    title: "Day 7 — The Feast of the Magnificat",
    category: "novenas",
    day: 7,
    intention: "To praise God with the joy of Mary",
    text: `O Saint Luke, you alone recorded the beautiful canticle of the Blessed Virgin Mary — the Magnificat — the song she sang when she visited her cousin Elizabeth. "My soul proclaims the greatness of the Lord; my spirit rejoices in God my Savior." You understood that this song was not merely a historical event, but a prophetic declaration of God's justice, mercy, and faithfulness. I pray today that I may sing my own Magnificat — that my soul may proclaim the greatness of the Lord, that my spirit may rejoice in God my Savior. Help me to see God's hand at work in my life, to recognize His blessings, and to give Him thanks with the same joy and gratitude that filled the heart of Mary. O Luke, who recorded the Magnificat, help me to praise God with all my heart. Amen.`,
  },
  {
    id: "slk-np-8",
    novenaId: "novenas-saint-luke",
    title: "Day 8 — The Patron of the Sick",
    category: "novenas",
    day: 8,
    intention: "For all who are ill and suffering",
    text: `O Saint Luke, patron of the sick, you who dedicated your life to healing the suffering, intercede today for all who are ill. There are millions throughout the world who lie upon beds of pain, who struggle with chronic illness, who face terminal diagnoses, who wait anxiously for medical results. I entrust them all to your intercession. You who healed so many in your earthly life, obtain for them the healing they need. If complete healing is not God's will, grant them the grace to bear their cross with patience and the assurance that they are never alone. Console the lonely, comfort the frightened, strengthen the weak, and give hope to the dying. Guide the hands of doctors and nurses, and bless the work of all who serve the sick with love and skill. O Luke, physician and patron of the sick, be their guardian and their hope. Amen.`,
  },
  {
    id: "slk-np-9",
    novenaId: "novenas-saint-luke",
    title: "Day 9 — The Evangelist's Crown",
    category: "novenas",
    day: 9,
    intention: "To live and die in faithful witness to the Gospel",
    text: `O glorious Saint Luke, Evangelist, Physician, and Apostle, on this final day of my novena, I commend myself to your powerful intercession. You who wrote the most comprehensive Gospel and the inspired history of the early Church, you who accompanied Saint Paul through every trial, you who healed the sick and painted the first icon of the Blessed Virgin — now stand before the throne of God as a glorious saint, bearing the crown of eternal life. I pray today that I may live and die in faithful witness to the Gospel that you so beautifully proclaimed. Help me to read your Gospel and the Acts of the Apostles with renewed love and understanding. Help me to carry the light of Christ to those around me, as you carried it to the ends of the ancient world. Help me to heal the sick, comfort the sorrowful, and bring the mercy of God to every person I encounter. And when my earthly life is complete, may I join you and all the saints in the eternal heavenly liturgy, where every tear is wiped away and every wound is healed. O Luke, beloved physician and evangelist, pray for me now and at the hour of my death. Amen.`,
  },
];
